export function conditionDescription(id:string,config:ConditionConfig={},state?:RuleState){const read=state?resolveConditions(state,config).read:undefined;const applicable=(row:{when?:string})=>!read||!row.when||evaluateExpression(row.when,read)===true;const d=conditionCatalog(config).find(d=>d.id===id);if(!d)return '';return [d.description,...(d.outputs??[]).map(o=>`${moduleTargets.find(([k])=>k===o.target)?.[1]} ${o.value>=0?'+':''}${o.value}`),...(d.skillModifiers??[]).map(m=>`${(m.ability?abilityNames[m.ability]:undefined)??m.skills?.map(id=>allSkills.find(s=>s.id===id)?.name).join('、')??'所有'}技能 ${m.value}`),...Object.entries(d.abilitySet??{}).map(([k,v])=>`${abilityNames[k]}设为${v}`),d.loseDex?'防御失去正的敏捷调整（保留负值）':null,d.speedMultiplier!==undefined?`速度×${d.speedMultiplier}`:null,...(d.implies??[]).filter(applicable).map(l=>`联动：${conditionCatalog(config).find(c=>c.id===l.id)?.name}`),...(d.notes??[]).filter(applicable).map(n=>n.text)].filter(Boolean).join('；')||'占位，暂不附加数值效果。'}
