export function clearBlockedConditions(state:RuleState,config:ConditionConfig){const blocked=resolveConditions(state,config).blocked;return {...state,conditions:{...state.conditions,...Object.fromEntries([...blocked].map(id=>[id,false]))}}}
export function applyExpiredTimedConditions(previous:RuleState,next:RuleState,config:ConditionConfig){let state=next;for(const timer of previous.timedEffects??[]){if(timer.remaining<=0||!timer.onExpireConditions?.length)continue;const current=next.timedEffects?.find(t=>t.id===timer.id);if(!current||current.remaining<=0)state={...state,conditions:{...state.conditions,...Object.fromEntries(timer.onExpireConditions.map(id=>[id,true]))}}}return clearBlockedConditions(state,config)}
